function searchResults(query){const q=normalizeSearchQuery(query).toLowerCase();if(!q)return [];const all=[...APPS.map(a=>({id:a.id,label:a.title,kind:'app',description:a.description,icon:a.icon,searchableText:a.description,go:()=>openWindow(a.id)})),...state.shortcuts.map(s=>({id:s.id,label:s.name,kind:'shortcut',description:'Website shortcut',icon:s.icon,searchableText:s.url,go:()=>openExternal(s.url)})),...state.files.map(f=>({id:f.id,label:f.name,kind:'file',description:f.type==='folder'?'Folder':'Workspace file',icon:f.type==='folder'?'▱':'▤',searchableText:'',go:()=>openWindow('files',f.type==='folder'?{folder:f.id}:{folder:f.parent,file:f.id})})),...state.notes.map(n=>({id:n.id,label:n.title,kind:'note',description:'Note',icon:'≡',searchableText:n.content,go:()=>openWindow('notes',{note:n.id})})),...['appearance','taskbar','search','data'].map(id=>({id:'setting-'+id,label:id[0].toUpperCase()+id.slice(1)+' settings',kind:'setting',description:'Settings section',icon:'⚙',searchableText:id,go:()=>openWindow('settings',{setting:id})}))];return all.map(x=>({...x,score:x.label.toLowerCase()===q?0:x.label.toLowerCase().startsWith(q)?1:x.label.toLowerCase().includes(q)?2:(x.searchableText+' '+x.description).toLowerCase().includes(q)?3:99})).filter(x=>x.score<99).sort((a,b)=>a.score-b.score||a.label.localeCompare(b.label)).slice(0,10)}
