function overlayKeys(e){if(e.key==='Escape'){if($('#dialog').open)return;if(!$('#menu').hidden){e.preventDefault();closeMenu();return}e.preventDefault();closeOverlay();return}if(state.ui.overlay==='launcher'&&['ArrowDown','ArrowUp','ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();const nodes=[...$('#overlay').querySelectorAll('.launch-card:not(:disabled)')],i=nodes.indexOf(document.activeElement),delta=['ArrowDown','ArrowRight'].includes(e.key)?1:-1;nodes[Math.max(0,Math.min(nodes.length-1,i+delta))]?.focus()}if(state.ui.overlay!=='search')return;const count=state.ui.results.length||getRecentSearches().length;if(['ArrowDown','ArrowUp'].includes(e.key)){e.preventDefault();state.ui.resultIndex=Math.max(0,Math.min(count-1,state.ui.resultIndex+(e.key==='ArrowDown'?1:-1)));const inputFocus=document.activeElement?.id==='global-query';renderSearch();$('#overlay [aria-selected=true]')?.scrollIntoView({block:'nearest'});if(inputFocus)$('#global-query').focus()}else if(e.key==='Enter'&&document.activeElement?.id==='global-query'){e.preventDefault();const r=state.ui.results[state.ui.resultIndex];if(r)executeSearch(r);else if(!normalizeSearchQuery(state.ui.query)){const h=getRecentSearches()[state.ui.resultIndex];if(h){state.ui.query=h.query;renderSearch()}}}else if(e.key==='Delete'&&!state.ui.query&&count){e.preventDefault();removeSearchHistory(getRecentSearches()[state.ui.resultIndex]?.id)}}
