function renderWelcome(root){root.replaceChildren();const hero=el('div',null,'hero');hero.append(el('span','FRONTEND FUSION CLOUD OS','eyebrow'),el('h2',state.profile.name?'Hello, '+state.profile.name+'.':'Make room for your next idea.'),el('p','A small desktop for the things you are working on. Write a note, organise files, or keep a favourite website close.'));root.append(hero);const cards=el('div',null,'cards');for(const id of ['files','notes','browser','settings']){const a=getApp(id),b=btn(null,()=>openWindow(id));b.append(icon(a.icon),el('span',a.title));b.lastChild.append(el('small',a.description));cards.append(b)}root.append(cards,notice('Despite the name, this is a browser-local web app, not a real operating system or cloud service. Data stays in this browser profile. Export backups; clearing browser data removes it.'));const recent=[...state.files.filter(f=>f.type!=='folder').map(f=>({label:f.name,time:f.modified,go:()=>openWindow('files',{folder:f.parent,file:f.id})})),...state.notes.map(n=>({label:n.title,time:n.modified,go:()=>openWindow('notes',{note:n.id})}))].sort((a,b)=>b.time-a.time).slice(0,3);if(recent.length){root.append(el('h3','Recently changed'));for(const x of recent)root.append(btn(x.label,x.go))}root.append(el('p','Tip: press Ctrl / Cmd + K to find anything in your workspace.','small muted'))}
function createFile(type){const [l,input]=field(type==='folder'?'Folder name':'File name',type==='folder'?'New folder':'Untitled.txt');showFormDialog(type==='folder'?'New folder':'New text file',[l],()=>{const name=input.value.trim();if(!name){announce('A name is required.');return false}state.files.push({id:uid(),name:name.slice(0,200),type,parent:validFolder(state.ui.folder),content:'',assetId:null,mime:type==='text'?'text/plain':'',modified:Date.now()});persist(true);refreshApps();announce(type==='folder'?'Folder created':'Text file created')})}
