function renderNotes(root){root.replaceChildren();const bar=el('div',null,'toolbar');bar.append(btn('＋ New note',newNote));root.append(bar);const layout=el('div',null,'note-layout'),list=el('div',null,'note-list'),editor=el('div',null,'note-editor');for(const n of [...state.notes].sort((a,b)=>b.modified-a.modified)){const b=btn(n.title,()=>{state.ui.noteId=n.id;trackLast('note',n.id,n.title);renderApp('notes')});b.dataset.noteId=n.id;b.classList.toggle('primary',state.ui.noteId===n.id);list.append(b)}let note=state.notes.find(n=>n.id===state.ui.noteId);if(!note&&state.notes.length){note=state.notes[0];state.ui.noteId=note.id}if(note){const title=el('input');title.value=note.title;title.setAttribute('aria-label','Note title');const content=el('textarea');content.value=note.content;content.setAttribute('aria-label','Note content');const modified=el('small',new Date(note.modified).toLocaleString(),'muted');const save=()=>{note.title=title.value.slice(0,200)||'Untitled note';note.content=content.value;note.modified=Date.now();modified.textContent='Saving locally...';persist();clearTimeout(state.ui.noteTimer);state.ui.noteTimer=setTimeout(()=>{modified.textContent=state.ui.lastSaveOK&&!state.ui.storageBlocked?'Saved locally · '+new Date(note.modified).toLocaleTimeString():'Not saved: export a backup';const b=[...list.children].find(b=>b.dataset.noteId===note.id);if(b)b.textContent=note.title},500)};title.addEventListener('input',save);content.addEventListener('input',save);editor.append(title,content,modified,btn('Delete note',()=>deleteNote(note),'danger'))}else editor.append(empty('Create your first note. Reopening Notes never creates blank notes.'));layout.append(list,editor);root.append(layout)}
