document.addEventListener('pointerdown',e=>{if(!$('#profile-card').hidden&&!e.target.closest('#profile-card,#profile-toggle'))closeProfileCard(false)});
async function makeAvatar(file){if(!['image/png','image/jpeg','image/webp'].includes(file.type))throw new Error('Choose a PNG, JPEG or WebP image.');if(file.size>8*1024*1024)throw new Error('Choose an image under 8 MB.');let bmp;try{bmp=await createImageBitmap(file)}catch{throw new Error('That image could not be read.')}const S=256,c=document.createElement('canvas');c.width=c.height=S;const g=c.getContext('2d'),m=Math.min(bmp.width,bmp.height);g.drawImage(bmp,(bmp.width-m)/2,(bmp.height-m)/2,m,m,0,0,S,S);bmp.close?.();let u=c.toDataURL('image/webp',.85);if(!u.startsWith('data:image/webp'))u=c.toDataURL('image/jpeg',.85);if(!AVATAR_RE.test(u)||u.length>200000)throw new Error('That image is too detailed to store. Try a smaller photo.');return u}
function editProfile(){const p=state.profile;let avatar=p.avatar;const [nl,ni]=field('Display name',p.name);ni.maxLength=60;ni.autocomplete='name';const [rl,ri]=field('Role',p.role);ri.maxLength=60;const [wl,wi]=field('Workspace name',p.workspace);wi.maxLength=60;wi.placeholder='Frontend Fusion';const sl=el('label','Avatar shape'),ss=el('select');for(const x of SHAPES){const o=el('option',x[0].toUpperCase()+x.slice(1));o.value=x;ss.append(o)}ss.value=p.shape;sl.append(ss);const prev=el('div',null,'avatar-edit');const draw=()=>{const tmp={...state.profile,avatar,shape:ss.value,name:ni.value.trim()};const keep=state.profile;state.profile=tmp;const n=avatarNode('lg');state.profile=keep;prev.replaceChildren(n)};const fi=document.createElement('input');fi.type='file';fi.accept='image/png,image/jpeg,image/webp';fi.setAttribute('aria-label','Upload avatar image');fi.addEventListener('change',async()=>{const f=fi.files[0];if(!f)return;try{avatar=await makeAvatar(f);draw()}catch(err){announce(err.message);fi.value=''}});const rm=btn('Remove photo',()=>{avatar=null;fi.value='';draw()});ss.addEventListener('change',draw);ni.addEventListener('input',draw);draw();const fl=el('label','Avatar photo (cropped square, stored in this browser)');fl.append(fi);showFormDialog('Edit profile',[prev,nl,rl,wl,sl,fl,rm],()=>{state.profile={...state.profile,name:ni.value.trim().slice(0,60),role:ri.value.trim().slice(0,60),workspace:wi.value.trim().slice(0,60),shape:ss.value,avatar};state.profile=normProfile(state.profile);if(!persist(true))announce('Profile changed but could not be saved. Export a backup.');renderProfile();refreshApps(['welcome']);announce('Profile saved')},'Save profile')}
function exportProfile(){download(new Blob([JSON.stringify({app:'frontend-fusion-profile',schemaVersion:1,exportedAt:new Date().toISOString(),profile:{...state.profile,lastOpened:null},preferences:{appearance:state.preferences.appearance,accentColor:state.preferences.accentColor}},null,2)],{type:'application/json'}),'fusion-profile.json');announce('Profile exported')}
$('#profile-import-input').addEventListener('change',async e=>{const f=e.target.files[0];e.target.value='';if(!f)return;try{if(f.size>600*1024)throw new Error('Profile files must be under 600 KB.');const raw=JSON.parse(await f.text());if(!raw||raw.app!=='frontend-fusion-profile'||raw.schemaVersion!==1||!raw.profile||typeof raw.profile!=='object'||Array.isArray(raw.profile))throw new Error('This is not a Frontend Fusion profile file.');const np=normProfile(raw.profile);np.lastOpened=state.profile.lastOpened;const pr=raw.preferences&&typeof raw.preferences==='object'?raw.preferences:{};showConfirmDialog('Replace profile?','This replaces your name, role, workspace name, avatar and theme with "'+(np.name||'unnamed profile')+'". Notes, files and shortcuts are not changed.',()=>{state.profile=np;if(['dark','light','system'].includes(pr.appearance))state.preferences.appearance=pr.appearance;if(/^#[0-9a-f]{6}$/i.test(pr.accentColor))state.preferences.accentColor=pr.accentColor;applyPreferences();renderProfile();persist(true);announce('Profile imported')},'Replace profile')}catch(err){announce('Profile import rejected: '+err.message+' Existing profile is unchanged.')}});
window.addEventListener('error',e=>{announce('Something went wrong. Your saved data was not changed.')});window.addEventListener('unhandledrejection',()=>announce('Something went wrong. Your saved data was not changed.'));
async function start(){try{await initDB()}catch{announce('Binary storage unavailable. Notes and text files can still use LocalStorage.')}delete state.windows.welcome;await applyPreferences();renderDesktop();renderTaskbar();renderProfile();refreshMissingFavicons();if(Object.keys(state.windows).length){for(const id of Object.keys(state.windows)){createWindow(id);renderApp(id)}const top=Object.values(state.windows).filter(w=>!w.minimized).sort((a,b)=>b.z-a.z)[0];if(top)focusWindow(top.id)}else if(!state.onboarded){state.onboarded=true;persist(true);openWindow('welcome')}tick();setInterval(tick,30000);$('#boot').remove();if(storageFault)announce(storageFault);if('serviceWorker'in navigator){try{const reg=await navigator.serviceWorker.register('./sw.js');await navigator.serviceWorker.ready;$('#connection').textContent='Ready offline';reg.addEventListener('updatefound',()=>{const worker=reg.installing;worker?.addEventListener('statechange',()=>{if(worker.state==='installed'&&navigator.serviceWorker.controller)showConfirmDialog('App update ready','Your workspace data is kept. Reload to use the new app version.',()=>{worker.postMessage('ACTIVATE_UPDATE');navigator.serviceWorker.addEventListener('controllerchange',()=>location.reload(),{once:true})},'Update and reload')})})}catch{ $('#connection').textContent='Offline setup unavailable';announce('Offline setup needs HTTPS or localhost.')}}else $('#connection').textContent='Service workers unavailable'}
start().catch(err=>{const b=$('#boot');if(b)b.textContent='Could not open the workspace. '+err.message});
